document.addEventListener('DOMContentLoaded', () => {
  document.querySelectorAll('[data-mobile-menu]').forEach((button) => {
    button.addEventListener('click', () => {
      const nav = document.querySelector('[data-mobile-nav]');
      if (!nav) return;
      const open = nav.classList.toggle('is-open');
      button.setAttribute('aria-expanded', String(open));
    });
  });

  document.querySelectorAll('[data-variant-select]').forEach((select) => {
    select.addEventListener('change', (event) => {
      const option = event.target.options[event.target.selectedIndex];
      const form = event.target.closest('[data-product-form]');
      if (!form) return;
      const id = form.querySelector('input[name="id"]');
      const price = form.querySelector('[data-product-price]');
      const button = form.querySelector('[name="add"]');
      if (id) id.value = option.value;
      if (price) price.textContent = option.dataset.price || '';
      if (button) {
        button.disabled = option.dataset.available !== 'true';
        button.textContent = option.dataset.available === 'true' ? 'Add to bag' : 'Sold out';
      }
    });
  });
});

const limits = { name: 120, email: 254, company: 160, message: 4000 };
const interests = new Set(['', 'custom-software', 'nevora', 'other']);
export function validateInquiry(fields = {}) {
  const errors = {}, values = {};
  for (const key of Object.keys(limits)) {
    const input = fields?.[key];
    if (input !== undefined && typeof input !== 'string') { values[key] = ''; errors[key] = 'Enter text in this field.'; continue; }
    values[key] = (input || '').normalize('NFC').replace(/\r\n?/g, '\n').trim();
    if (values[key].length > limits[key]) errors[key] = 'Use ' + limits[key] + ' characters or fewer.';
  }
  if (!values.name && !errors.name) errors.name = 'Enter your name.';
  if ((!values.email || !/^[^\s@<>"\\,;]+@[^\s@<>"\\,;]+\.[^\s@<>"\\,;]+$/u.test(values.email)) && !errors.email) errors.email = 'Enter an email address we can reply to.';
  if (!values.message && !errors.message) errors.message = 'Tell us what you want to discuss.';
  values.interest = typeof fields?.interest === 'string' && interests.has(fields.interest) ? fields.interest : '';
  return { valid: Object.keys(errors).length === 0, errors, values };
}
export function createInquiryController({ mode = 'preview', transport, onState = () => {}, timeoutMs = 12000 } = {}) {
  if (!['preview', 'live'].includes(mode)) throw new TypeError('Unsupported inquiry mode');
  let state = Object.freeze({ status: 'idle' }), pending = null;
  const update = next => { state = Object.freeze(next); onState(state); return state; };
  function submit(fields) {
    if (pending) return pending;
    if (state.status === 'uncertain') return Promise.resolve(state);
    const checked = validateInquiry(fields);
    if (!checked.valid) return Promise.resolve(update({ status: 'invalid', errors: checked.errors }));
    if (mode === 'preview') {
      update({ status: 'checking' });
      pending = Promise.resolve().then(() => update({ status: 'preview' })).finally(() => { pending = null; });
      return pending;
    }
    if (typeof transport !== 'function') return Promise.resolve(update({ status: 'unavailable' }));
    update({ status: 'sending' });
    const abort = new AbortController();
    let timer;
    pending = (async () => {
      try {
        const timeout = new Promise((_, reject) => { timer = setTimeout(() => { abort.abort(); reject(new Error('Inquiry response deadline')); }, timeoutMs); });
        const result = await Promise.race([transport(checked.values, { signal: abort.signal }), timeout]);
        return update({ status: result?.accepted === true ? 'accepted' : 'failed' });
      } catch { return update({ status: 'uncertain' }); }
      finally { clearTimeout(timer); pending = null; }
    })();
    return pending;
  }
  return { submit, get state() { return state; }, reset() { if (pending) return state; return update({ status: 'idle' }); } };
}

const keys = ['analytics', 'marketing', 'preferences'];
const off = () => ({ analytics: false, marketing: false, preferences: false });
const valid = choices => choices && keys.every(key => typeof choices[key] === 'boolean');
export function createPrivacyAdapter(host = globalThis, { platform = host.document?.documentElement?.dataset.platform || 'shopify', timeoutMs = 5000 } = {}) {
  let local = off(), loaded;
  const toChoices = input => Object.fromEntries(keys.map(key => [key, input?.[key] === true || input?.[key] === 'yes']));
  async function resolveApi() {
    const current = host.Shopify?.customerPrivacy;
    if (current?.currentVisitorConsent && current?.setTrackingConsent) return current;
    if (!host.Shopify?.loadFeatures) return null;
    if (!loaded) loaded = new Promise(resolve => {
      let finished = false;
      const timer = setTimeout(() => { finished = true; resolve(null); }, timeoutMs);
      try {
        host.Shopify.loadFeatures([{ name: 'consent-tracking-api', version: '0.2' }], error => {
          if (finished) return;
          finished = true; clearTimeout(timer);
          resolve(error ? null : host.Shopify?.customerPrivacy || null);
        });
      } catch { finished = true; clearTimeout(timer); resolve(null); }
    });
    return loaded;
  }
  async function read() {
    if (platform === 'local') return { available: true, mode: 'local', choices: { ...local } };
    try {
      const api = await resolveApi();
      if (!api?.currentVisitorConsent || !api?.setTrackingConsent) return { available: false, mode: 'shopify', choices: off() };
      return { available: true, mode: 'shopify', choices: toChoices(api.currentVisitorConsent()) };
    } catch { return { available: false, mode: 'shopify', choices: off() }; }
  }
  async function save(choices) {
    if (!valid(choices)) return { ok: false, error: 'Invalid privacy choices.' };
    const clean = Object.fromEntries(keys.map(key => [key, choices[key]]));
    if (platform === 'local') { local = clean; return { ok: true, mode: 'local' }; }
    try {
      const api = await resolveApi();
      if (!api?.setTrackingConsent) return { ok: false, error: 'The platform privacy service is unavailable. Choices have not been saved.' };
      return await new Promise(resolve => {
        let finished = false;
        const timer = setTimeout(() => { finished = true; resolve({ ok: false, error: 'We could not confirm the privacy change. Try again later.' }); }, timeoutMs);
        try {
          api.setTrackingConsent(clean, error => {
            if (finished) return;
            finished = true; clearTimeout(timer);
            resolve(error ? { ok: false, error: 'The platform did not accept the privacy change.' } : { ok: true, mode: 'shopify' });
          });
        } catch { finished = true; clearTimeout(timer); resolve({ ok: false, error: 'The platform did not accept the privacy change.' }); }
      });
    } catch { return { ok: false, error: 'Privacy choices could not be saved.' }; }
  }
  return { read, save };
}

